#!/usr/bin/env python3
"""Demo data for the README screenshots: a fictional anzhiyu blog, generated by Hexo, and
demo.json, everything the mock backend answers with (app/scripts/readme/mock.ts).

    python3 app/scripts/readme/demo.py <demo folder>

Needs node / npm and the network the first time (theme, packages, pictures); later runs reuse
them. Nothing here reads or writes your own blogs or Hexo-Studio's data.
"""

import json
import os
import re
import shutil
import subprocess
import sys
import urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
APP = HERE.parent.parent
STARTER = APP / "src-tauri" / "starter"
DEMO = Path(sys.argv[1]).resolve()
BLOG = DEMO / "qingchuan-blog"
PORT = 4610
SITE = f"http://127.0.0.1:{PORT}"
TZ = "Asia/Shanghai"

# The same packages a new anzhiyu blog gets (domain/template.rs: BASE_PACKAGES + the template's plugins).
PACKAGES = ["hexo", "hexo-generator-archive", "hexo-generator-category", "hexo-generator-index", "hexo-generator-tag",
            "hexo-renderer-marked", "hexo-server", "hexo-renderer-pug", "hexo-renderer-stylus"]

TITLE, AUTHOR = "晴川的笔记", "晴川"

POSTS = [
    dict(slug="hexo-blog-setup", title="用 Hexo 搭一个自己的博客", date="2026-11-18 21:30:00", tags=["Hexo", "建站"], cats=["折腾"],
         desc="从 hexo init 到部署上线，一步一步记下来。", pic="hexo", body="""## 为什么选 Hexo

写博客最怕的是平台说没就没。Hexo 把文章留在自己手里：Markdown 文件、一个配置、一条部署命令。

{% note info simple %}
本文用的是 Hexo 8 和安知鱼主题，Node 需要 20.19 以上。
{% endnote %}

## 三步上线

1. `hexo init` 建好骨架，装上主题
2. 在 `source/_posts` 里写文章，`hexo server` 实时预览
3. `hexo deploy` 推到 GitHub Pages

{% image http://127.0.0.1:4610/img/desk.jpg, alt=写作的桌面 %}

## 小结

最难的不是搭建，而是坚持写下去。
"""),
    dict(slug="weekend-hiking", title="周末去山里走了二十公里", date="2026-11-09 19:12:00", tags=["徒步", "生活"], cats=["生活"],
         desc="秋天的山路，和一碗很好吃的面。", pic="hiking", body="早上六点出发，山里的雾还没散。\n\n![山路](http://127.0.0.1:4610/img/trail.jpg)\n\n- 全程 20.4 公里\n- 爬升 1100 米\n- 补给：两个饭团、一壶热茶\n"),
    dict(slug="rust-ownership", title="Rust 的所有权，用一张图讲清楚", date="2026-10-27 22:05:00", tags=["Rust", "编程"], cats=["技术"],
         desc="借用、移动和生命周期，其实是同一件事。", pic="rust", body="```rust\nlet s = String::from(\"hi\");\nlet t = s; // s 移动给了 t\n```\n\n所有权只有一个主人，借用可以有很多个读者。\n"),
    dict(slug="books-2026", title="今年读完的 24 本书", date="2026-10-12 10:40:00", tags=["读书"], cats=["生活"],
         desc="小说、历史和几本让人睡不着的科普。", pic="books", body="按读完的顺序排列，每本一句话。\n"),
    dict(slug="mac-photo-workflow", title="在 Mac 上整理照片的工作流", date="2026-09-21 16:20:00", tags=["Mac", "摄影"], cats=["折腾"],
         desc="导入、挑选、命名、备份，四步就够。", pic="photo", body="照片多了以后，找不到比拍不到更难受。\n"),
    dict(slug="kitchen-notes", title="厨房里的小实验", date="2026-11-20 23:10:00", tags=["做饭"], cats=["生活"],
         desc="", pic="kitchen", body="还没写完的草稿。\n", draft=True),
]

# picsum.photos seeds, fixed so the pictures stay the same between runs.
PICTURES = {"hexo": 1, "hiking": 1018, "rust": 0, "books": 24, "photo": 250, "kitchen": 292, "desk": 180, "trail": 1043}


def run(cmd, cwd=BLOG, **kw):
    print("  $", " ".join(map(str, cmd)), flush=True)
    subprocess.run(list(map(str, cmd)), cwd=cwd, check=True, env={**os.environ, "TZ": TZ, "NO_COLOR": "1"}, **kw)


def make_blog():
    if (BLOG / "node_modules" / "hexo").is_dir():
        return
    print("建示例博客（第一次需要联网，约半分钟）")
    shutil.rmtree(BLOG, ignore_errors=True)
    (BLOG / "themes").mkdir(parents=True)
    shutil.copytree(STARTER / "scaffolds", BLOG / "scaffolds")
    shutil.copy(STARTER / "gitignore", BLOG / ".gitignore")
    (BLOG / "package.json").write_text(json.dumps({"name": "hexo-site", "version": "0.0.0", "private": True, "hexo": {"version": ""}}, indent=2))
    run(["npm", "pack", "hexo-theme-anzhiyu@latest", "--pack-destination", "."])
    tarball = next(BLOG.glob("*.tgz"))
    run(["tar", "-xzf", tarball.name])
    tarball.unlink()
    (BLOG / "package").rename(BLOG / "themes" / "anzhiyu")
    run(["npm", "install", "--save", "--no-audit", "--no-fund", *PACKAGES])


def write_config():
    starter = (STARTER / "_config.yml").read_text()
    values = {"title": json.dumps(TITLE, ensure_ascii=False), "author": json.dumps(AUTHOR, ensure_ascii=False), "language": "zh-CN",
              "timezone": json.dumps(TZ), "theme": "anzhiyu", "url": "https://qingchuan.example.com"}
    lines = [f"{k}: {values[k]}" if (k := l.split(":")[0]) in values else l for l in starter.splitlines()]
    lines[-2:] = ["deploy:", "  type: git", "  repo: git@github.com:qingchuan/qingchuan.github.io.git", "  branch: main"]
    (BLOG / "_config.yml").write_text("\n".join(lines) + "\n")
    # The theme's own defaults, with its sample menu switched on so the menu has something in it.
    theme = (BLOG / "themes/anzhiyu/_config.yml").read_text()
    head, rest = theme.split("\n", 30)[:30], theme.split("\n", 30)[30]
    head = [re.sub(r"^  # (\s*)(文章|隧道|分类|标签|关于|关于本人):", r"  \1\2:", l) for l in head]
    (BLOG / "_config.anzhiyu.yml").write_text("\n".join(head) + "\n" + rest)


def pictures():
    img = BLOG / "source" / "img"
    img.mkdir(parents=True, exist_ok=True)
    for name, seed in PICTURES.items():
        path = img / f"{name}.jpg"
        if not path.exists():
            print(f"  下载配图 {name}", flush=True)
            urllib.request.urlretrieve(f"https://picsum.photos/id/{seed}/1200/800", path)


def front_matter(p):
    tags = "\n".join(f"  - {t}" for t in p["tags"])
    cats = "\n".join(f"  - {c}" for c in p["cats"])
    return f"title: {p['title']}\ndate: {p['date']}\ntags:\n{tags}\ncategories:\n{cats}\ncover: {SITE}/img/{p['pic']}.jpg\ndescription: {p['desc']}\n"


def write_posts():
    for d in ["_posts", "_drafts"]:
        shutil.rmtree(BLOG / "source" / d, ignore_errors=True)
        (BLOG / "source" / d).mkdir(parents=True)
    for p in POSTS:
        folder = "_drafts" if p.get("draft") else "_posts"
        (BLOG / "source" / folder / f"{p['slug']}.md").write_text(f"---\n{front_matter(p)}---\n{p['body']}")


def url_path(p):
    y, m, d = p["date"][:10].split("-")
    return f"{y}/{m}/{d}/{p['slug']}/"


def demo_json():
    def stamp(date):
        return int(subprocess.run(["date", "-j", "-f", "%Y-%m-%d %H:%M:%S", date, "+%s"], capture_output=True, text=True, env={**os.environ, "TZ": TZ}).stdout)

    posts, files = [], {}
    for p in POSTS:
        folder = "_drafts" if p.get("draft") else "_posts"
        summary = dict(id=f"{folder}/{p['slug']}.md", kind="draft" if p.get("draft") else "post", fileName=f"{p['slug']}.md", title=p["title"],
                       date=p["date"], tags=p["tags"], categories=p["cats"], urlPath=url_path(p), modified=stamp(p["date"]))
        posts.append(summary)
        files[summary["id"]] = dict(summary=summary, prefix="---\n", yaml=front_matter(p), suffix="---\n", body=p["body"], fingerprint=p["slug"])
    deps = json.loads((BLOG / "package.json").read_text())["dependencies"]
    plugins = []
    for name in sorted(deps):
        manifest = json.loads((BLOG / "node_modules" / name / "package.json").read_text())
        if name.startswith("hexo-") and not name.startswith("hexo-theme-"):
            plugins.append(dict(name=name, wanted=deps[name], version=manifest.get("version"), description=manifest.get("description"),
                                repo=None, fromTheme=name in ("hexo-renderer-pug", "hexo-renderer-stylus")))
    used = {name: [] for name in PICTURES}
    for p in POSTS:
        folder = "_drafts" if p.get("draft") else "_posts"
        used[p["pic"]].append(f"source/{folder}/{p['slug']}.md")
    used["desk"].append("source/_posts/hexo-blog-setup.md")
    used["trail"].append("source/_posts/weekend-hiking.md")
    names = {"hexo": "Hexo 封面", "hiking": "山里的雾", "rust": "代码与咖啡", "books": "书架", "photo": "相机", "kitchen": "厨房", "desk": "写作的桌面", "trail": "山路"}
    images = []
    for i, (key, seed) in enumerate(PICTURES.items()):
        size = (BLOG / "source/img" / f"{key}.jpg").stat().st_size
        url = f"{SITE}/img/{key}.jpg"
        images.append(dict(id=f"img{i}", name=names[key], description=f"{names[key]} · 文章配图", ok=None if key == "kitchen" else True,
                           key=f"qingchuan-blog/{seed:08x}.webp", url=url, uploadedAt="2026-11-1" + str(i % 9), mirrors=[], format="webp",
                           bytes=size // 3, width=1200, height=800, original=dict(fileName=f"IMG_{2400 + i}.HEIC", bytes=size * 4, backup=""),
                           legacyUrls=[], usedBy=used[key], check=None, backupPath=None, thumb=url, profile="oss"))
    data = dict(
        blog=str(BLOG), site=SITE, port=PORT, title=TITLE, author=AUTHOR, posts=posts, files=files, plugins=plugins, images=images,
        titles={s["id"].replace("_posts", "source/_posts").replace("_drafts", "source/_drafts"): s["title"] for s in posts},
        config={"site": (BLOG / "_config.yml").read_text(), "theme": (BLOG / "_config.anzhiyu.yml").read_text(),
                "themeDefaults": (BLOG / "themes/anzhiyu/_config.yml").read_text()},
    )
    (DEMO / "demo.json").write_text(json.dumps(data, ensure_ascii=False))


DEMO.mkdir(parents=True, exist_ok=True)
make_blog()
write_config()
pictures()
write_posts()
print("生成示例博客的网页")
run(["node", "node_modules/.bin/hexo", "clean"], stdout=subprocess.DEVNULL)
run(["node", "node_modules/.bin/hexo", "generate"], stdout=subprocess.DEVNULL)
demo_json()
print(f"示例数据：{DEMO}")
